package br.com.flaviotorres.iptvpremium.data.cache.dao

/** Non-null SQL predicate shared by menu counts, grid and poster prefetch. */
internal const val MOVIE_IS_SUBTITLED_SQL = """(COALESCE(UPPER(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((' ' || name || ' '), '[', ' '), ']', ' '), '(', ' '), ')', ' '), '|', ' '), '-', ' '), '_', ' '), '/', ' '), '{', ' '), '}', ' ')), '') LIKE '% L %' OR COALESCE(UPPER(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((' ' || name || ' '), '[', ' '), ']', ' '), '(', ' '), ')', ' '), '|', ' '), '-', ' '), '_', ' '), '/', ' '), '{', ' '), '}', ' ')), '') LIKE '% LEG %' OR COALESCE(UPPER(name), '') LIKE '%LEGENDAD%' OR COALESCE(categoryId, '') IN (SELECT categoryId FROM cached_categories WHERE playlistId = :playlistId AND generationId = :generationId AND type = 'MOVIES' AND (LOWER(name) LIKE '%legendad%' OR COALESCE(UPPER(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace((' ' || name || ' '), '[', ' '), ']', ' '), '(', ' '), ')', ' '), '|', ' '), '-', ' '), '_', ' '), '/', ' '), '{', ' '), '}', ' ')), '') LIKE '% LEG %')))"""
